<template><view class="splash"><view class="skip" @tap="skip">跳过 {{countdown}}</view><image src="/static/navigation/sravx-mark.png" mode="aspectFit"/></view></template>
<script>import api from '../../common/api.js';import auth from '../../common/auth.js';export default{data(){return{countdown:3,timer:null}},onLoad(){this.login();this.start()},onUnload(){this.stop()},methods:{async login(){try{const result=await api.login();auth.save(result||{})}catch(error){}},start(){this.timer=setInterval(()=>{this.countdown--;if(this.countdown<=0){this.stop();this.go()}},1000)},stop(){if(this.timer){clearInterval(this.timer);this.timer=null}},skip(){this.stop();this.go()},go(){uni.reLaunch({url:'/pages/index/index'})}}}</script>
<style>.splash{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;background:#fff}.splash image{width:160px;height:200px}.skip{position:absolute;right:16px;bottom:calc(24px + env(safe-area-inset-bottom));z-index:2;padding:6px 14px;border:1px solid rgba(0,0,0,.1);border-radius:18px;background:rgba(0,0,0,.08);color:#636366;font-size:12px}</style>
